import java.util.*;

class Solution {
    public String decodeString(String s) {
        Deque<Integer> countStack = new ArrayDeque<>();
        Deque<StringBuilder> builderStack = new ArrayDeque<>();
        StringBuilder current = new StringBuilder();
        int repeat = 0;

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (Character.isDigit(c)) {
                repeat = repeat * 10 + (c - '0');
            } else if (c == '[') {
                countStack.push(repeat);
                builderStack.push(current);
                repeat = 0;
                current = new StringBuilder();
            } else if (c == ']') {
                int times = countStack.pop();
                StringBuilder previous = builderStack.pop();
                appendRepeated(previous, current, times);
                current = previous;
            } else {
                current.append(c);
            }
        }

        return current.toString();
    }

    private void appendRepeated(StringBuilder target, StringBuilder segment, int times) {
        for (int i = 0; i < times; i++) {
            target.append(segment);
        }
    }
}

import java.util.*;

class Solution {
    private static class Frame {
        final StringBuilder previous;
        final int repeat;

        Frame(StringBuilder previous, int repeat) {
            this.previous = previous;
            this.repeat = repeat;
        }
    }

    public String decodeString(String s) {
        Deque<Frame> frames = new ArrayDeque<>();
        StringBuilder current = new StringBuilder();
        int repeat = 0;

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (Character.isDigit(c)) {
                repeat = repeat * 10 + (c - '0');
            } else if (c == '[') {
                frames.push(new Frame(current, repeat));
                current = new StringBuilder();
                repeat = 0;
            } else if (c == ']') {
                Frame frame = frames.pop();
                StringBuilder expanded = frame.previous;
                for (int j = 0; j < frame.repeat; j++) {
                    expanded.append(current);
                }
                current = expanded;
            } else {
                current.append(c);
            }
        }

        return current.toString();
    }
}

class Solution {
    private int index;

    public String decodeString(String s) {
        index = 0;
        return parseSegment(s);
    }

    private String parseSegment(String s) {
        StringBuilder result = new StringBuilder();
        while (index < s.length() && s.charAt(index) != ']') {
            char c = s.charAt(index);
            if (Character.isDigit(c)) {
                int repeat = 0;
                while (index < s.length() && Character.isDigit(s.charAt(index))) {
                    repeat = repeat * 10 + (s.charAt(index) - '0');
                    index++;
                }
                index++; // skip '['
                String decoded = parseSegment(s);
                index++; // skip ']'
                appendRepeated(result, decoded, repeat);
            } else {
                result.append(c);
                index++;
            }
        }
        return result.toString();
    }

    private void appendRepeated(StringBuilder result, String decoded, int repeat) {
        for (int i = 0; i < repeat; i++) {
            result.append(decoded);
        }
    }
}

import java.util.*;

class Solution {
    public String decodeString(String s) {
        Deque<String> stack = new ArrayDeque<>();

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c != ']') {
                stack.push(String.valueOf(c));
                continue;
            }

            StringBuilder segment = new StringBuilder();
            while (!stack.peek().equals("[")) {
                segment.insert(0, stack.pop());
            }
            stack.pop();

            StringBuilder countText = new StringBuilder();
            while (!stack.isEmpty() && Character.isDigit(stack.peek().charAt(0))) {
                countText.insert(0, stack.pop());
            }
            int repeat = Integer.parseInt(countText.toString());

            StringBuilder expanded = new StringBuilder();
            for (int j = 0; j < repeat; j++) {
                expanded.append(segment);
            }
            stack.push(expanded.toString());
        }

        StringBuilder result = new StringBuilder();
        while (!stack.isEmpty()) {
            result.insert(0, stack.pop());
        }
        return result.toString();
    }
}
